package com.rustyrazorblade.easydblab.events

/**
 * Event listener that renders events to the console (stdout/stderr).
 *
 * Uses [Event.toDisplayString] to produce the exact same output that was previously
 * generated by `outputHandler.handleMessage()`. Error events are written to stderr. An event whose
 * [Event.showOnConsole] is false is not printed, unless it is an error.
 */
class ConsoleEventListener : EventListener {
    override fun onEvent(envelope: EventEnvelope) {
        val event = envelope.event
        when {
            event.isError() -> System.err.println(event.toDisplayString())
            event.showOnConsole() -> println(event.toDisplayString())
        }
    }

    override fun close() {
        // No-op for console output
    }
}
